-- 这个表开发时要注意 project_id 不是 unique key ，一个project 允许跨region
CREATE TEMPORARY VIEW project_data_${grass_region_without_quote} AS
select
     id
    ,pname
    ,pdesc
    ,pics -- pic
    ,members  --pics
    ,state
    ,creator
    ,is_deleted
    ,uniq_priority
    ,layer_ids
    ,create_time
    ,update_time
FROM srdi_mart.ods_sr_data_warehouse_shopee_traffic_mangement_db__project_tab
where regional_date = ${regional_date} and regional_hour = ${regional_hour}
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW rule_data_${grass_region_without_quote} AS
SELECT
     project_id
    ,concat_ws(',',collect_set(if(state=3,scene,null))) as scenes
    ,min(start_time) as start_time
    ,if(min(end_time)=-1,-1,max(end_time)) as end_time
    ,concat_ws(',',collect_set(rule_id)) as local_rule_ids
FROM srdi_mart.dim_sr_data_warehouse_tc_rule
lateral view explode(from_json(scenes,'ARRAY<string>')) b as scene
where regional_date = ${regional_date} and regional_hour = ${regional_hour}  and grass_region IN (${grass_region})
and project_id is not null
group by project_id
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW rule_ids_${grass_region_without_quote} AS
SELECT
     project_id
    ,concat_ws(',',collect_set(rule_id)) as rule_ids
FROM srdi_mart.dim_sr_data_warehouse_tc_rule
where regional_date = ${regional_date} and regional_hour = ${regional_hour}
and project_id is not null
group by project_id
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dim_sr_data_warehouse_tc_biz_project partition(grass_region = ${grass_region},regional_date,regional_hour)
select
     a.project_id
    ,pname
    ,pdesc
    ,pics -- pic
    ,members  --pics
    ,state
    ,creator
    ,is_deleted
    ,uniq_priority
    ,layer_ids
    ,create_time
    ,update_time
    ,scenes
    ,start_time
    ,end_time
    ,local_rule_ids
    ,rule_ids

    ,cast(${regional_date} as date) as regional_date
    ,cast(${regional_hour} as int) as regional_hour
from rule_data_${grass_region_without_quote} a
inner join project_data_${grass_region_without_quote} b on a.project_id=b.id
inner join rule_ids_${grass_region_without_quote} c on a.project_id=c.project_id
;
